CREATE OR REPLACE FUNCTION public.guard_platform_values() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ BEGIN IF TG_TABLE_NAME='platform_overrides' THEN IF NEW.ends_at<=NEW.starts_at THEN RAISE EXCEPTION 'Promotion end must follow its start'; END IF; END IF; IF TG_TABLE_NAME='platform_products' THEN IF NEW.currency!~'^[A-Z]{3}$' THEN RAISE EXCEPTION 'Use a three-letter currency'; END IF; IF NEW.app_url<>'' AND NEW.app_url!~'^https://' THEN RAISE EXCEPTION 'Use a secure application URL'; END IF; END IF; RETURN NEW; END $$;